const parsed = JSON.parse($input.first().json.stdout);
const analysis = Array.isArray(parsed) ? parsed[0] : parsed;

const nrOfSteps = Number($('run_args').first().json.nr_of_steps);
const snakeIds = (analysis.snake_ids ?? []).map(String);
const fatalStepsObj = analysis.fatal_steps ?? {};
const enteredSeparateArea = analysis.entered_separate_area ?? {};
const tailVisiblePhases = analysis.tail_visible_phases ?? {};
const traps_mapping = analysis.traps_mapping ?? {};
const total_traps_made = {};

for (const traps of Object.values(traps_mapping)) {
  for (const trap of traps) {
    for (const id of trap.trapping_ids) {
      if (total_traps_made[id]){
        total_traps_made[id] += 1
      } 
      else {
        total_traps_made[id] = 1
      }
    }
  }
}

let video_end_step;

// Multiple snakes
if (snakeIds.length > 1) {
  const fatalSteps = Object.values(fatalStepsObj)
    .map(Number)
    .filter(Number.isFinite)
    .sort((a, b) => a - b);

  if (fatalSteps.length >= snakeIds.length) {
    // All snakes died -> one snake left after the second highest fatal step
    video_end_step = fatalSteps[fatalSteps.length - 2] + 50;
  } else if (fatalSteps.length > 0) {
    // Last snake never died -> one snake left after the highest fatal step
    video_end_step = fatalSteps[fatalSteps.length - 1] + 50;
  } else {
    // No deaths at all -> fallback
    video_end_step = Number(analysis.final_step_idx ?? 0);
  }
} else {
  // Single snake
  const snakeId = snakeIds[0] ?? "0";
  const lastEnteredSeparateAreaStep = Math.max(
    -Infinity,
    ...(enteredSeparateArea[snakeId] ?? []).map(Number).filter(Number.isFinite)
  );

  const phases = tailVisiblePhases[snakeId] ?? [];

  const matchingPhase = phases.find(
    (p) =>
      p.tail_visible === true &&
      Number.isFinite(Number(p.start_step_idx)) &&
      Number(p.start_step_idx) > lastEnteredSeparateAreaStep
  );

  if (matchingPhase) {
    video_end_step = Number(matchingPhase.start_step_idx) + 50;
  } else {
    // Fallback if no such phase exists
    video_end_step = Number(analysis.final_step_idx ?? 0);
  }
}

let video_start_step = video_end_step - nrOfSteps;
if (video_start_step < 0) {
  video_start_step = 0;
  // if start steps is 0 then we should not finish the video at the calculated end step
  video_end_step = nrOfSteps;
}


return [
  {
    json: {
      ...analysis,
      video_start_step,
      video_end_step,
      total_traps_made
    },
  },
];

