let video_json = JSON.parse($input.first().json.stdout)

let snake_values = $('Parse run analysis').first().json.env_meta_data.snake_values

let color_map = video_json.color_map

const result = Object.fromEntries(Object.entries(snake_values).map(([snakeId, { head_value, body_value }]) => [
        snakeId,
        {
            head_color: color_map[head_value],
            body_color: color_map[body_value]
        }
    ])
);

return [{video_json, snake_colors: result}]

